def _sha256(data):
    return hashlib.sha256(data).hexdigest()


def _is_lower_hex(value, length):
    if not isinstance(value, str) or len(value) != length:
        return False
    for character in value:
        if character not in "0123456789abcdef":
            return False
    return True


def _decimal(value, positive):
    if not value or (len(value) > 1 and value[0] == "0"):
        raise ValueError("decimal")
    if any(character not in "0123456789" for character in value):
        raise ValueError("decimal")
    number = int(value)
    if number > 18446744073709551615 or (positive and number == 0):
        raise ValueError("decimal")
    return number


def _token(value):
    if not value or len(value) > 255:
        raise ValueError("token")
    for character in value:
        if character not in "abcdefghijklmnopqrstuvwxyz0123456789._-":
            raise ValueError("token")
    return value


def _decode_hex(value, limit):
    if value == "-":
        raise ValueError("hex")
    if len(value) % 2 != 0 or len(value) // 2 > limit:
        raise ValueError("hex")
    if any(character not in "0123456789abcdef" for character in value):
        raise ValueError("hex")
    return bytes.fromhex(value)


def _decode_text_hex(value, limit):
    data = _decode_hex(value, limit)
    text = data.decode("utf-8", "strict")
    if not text or "\x00" in text or "\r" in text or "\n" in text or "\t" in text:
        raise ValueError("text")
    return text


def _absolute_path(value):
    if not isinstance(value, str) or not value.startswith("/") or value == "/":
        raise ValueError("path")
    if "\x00" in value or "\r" in value or "\n" in value or "\t" in value:
        raise ValueError("path")
    components = value.split("/")[1:]
    if any(not component or component == "." or component == ".." for component in components):
        raise ValueError("path")
    if os.fsdecode(os.fsencode(value)) != value:
        raise ValueError("path")
    return value


def _immutable_value(value):
    if value is None or isinstance(value, (bool, int, str, bytes)):
        return True
    if isinstance(value, tuple):
        return all(_immutable_value(item) for item in value)
    return False


def _canonical_value(value):
    if value is None:
        return b"n"
    if value is True:
        return b"b1"
    if value is False:
        return b"b0"
    if isinstance(value, int):
        return b"i" + str(value).encode("ascii") + b";"
    if isinstance(value, bytes):
        return b"y" + str(len(value)).encode("ascii") + b":" + value.hex().encode("ascii") + b";"
    if isinstance(value, str):
        encoded = value.encode("utf-8")
        return b"s" + str(len(encoded)).encode("ascii") + b":" + encoded.hex().encode("ascii") + b";"
    if isinstance(value, tuple):
        return b"t" + str(len(value)).encode("ascii") + b":" + b"".join(_canonical_value(item) for item in value) + b";"
    if isinstance(value, list):
        return b"l" + str(len(value)).encode("ascii") + b":" + b"".join(_canonical_value(item) for item in value) + b";"
    if isinstance(value, dict):
        rows = tuple(sorted((_canonical_value(key), _canonical_value(item)) for key, item in value.items()))
        return b"d" + str(len(rows)).encode("ascii") + b":" + b"".join(key + item for key, item in rows) + b";"
    raise ValueError("canonical-value")


def _write_diagnostic(error):
    name = type(error).__name__
    data = ("launcher_error=" + name + "\n").encode("ascii", "strict")
    try:
        os.write(2, data)
    except BaseException:
        pass


def _entry_fd_limit():
    soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    limit = hard
    if limit == resource.RLIM_INFINITY:
        limit = soft
    if limit == resource.RLIM_INFINITY or limit < 3 or limit > _MAX_FDS:
        raise RuntimeError("fd-limit")
    return int(limit)


def _fd_seekable(fd):
    try:
        os.lseek(fd, 0, os.SEEK_CUR)
    except OSError as error:
        if error.errno == errno.ESPIPE:
            return False
        raise
    return True


def _entry_fd_rows():
    limit = _entry_fd_limit()
    open_fds = []
    for fd in range(limit):
        try:
            flags = fcntl.fcntl(fd, fcntl.F_GETFD)
        except OSError as error:
            if error.errno == errno.EBADF:
                continue
            raise
        status_flags = fcntl.fcntl(fd, fcntl.F_GETFL)
        observed = os.fstat(fd)
        open_fds.append((fd, flags, status_flags & os.O_ACCMODE, stat.S_IFMT(observed.st_mode), observed.st_dev, observed.st_ino, observed.st_rdev, _fd_seekable(fd)))
    return tuple(open_fds)


def _validate_entry_model(argv, environment, cwd, incoming_umask, fd_rows, dev_null, flags, cwd_binding):
    if len(argv) != 2 or argv[0] != _LAUNCHER or argv[1] not in _MODES:
        raise ValueError("argv")
    if environment != _EXPECTED_ENV:
        raise ValueError("environment")
    if cwd != _EMPTY_CWD or incoming_umask != 63:
        raise ValueError("cwd-umask")
    if not isinstance(cwd_binding, tuple) or len(cwd_binding) != 4:
        raise ValueError("cwd-binding")
    logical_realpath, cwd_identity, logical_identity, physical_identity = cwd_binding
    if logical_realpath != _EMPTY_CWD or cwd_identity != logical_identity or cwd_identity != physical_identity:
        raise ValueError("cwd-binding")
    if len(cwd_identity) != 7 or cwd_identity[2] != stat.S_IFDIR or cwd_identity[4] != 0 or cwd_identity[3] & 0o022:
        raise ValueError("cwd-metadata")
    if flags != (1, 1, 1, 1):
        raise ValueError("python-flags")
    if len(fd_rows) != 3 or tuple(row[0] for row in fd_rows) != (0, 1, 2):
        raise ValueError("fd-table")
    stdin_row, stdout_row, stderr_row = fd_rows
    if stdin_row[2] != os.O_RDONLY or stdin_row[3] != stat.S_IFCHR:
        raise ValueError("stdin")
    if stdin_row[4:7] != dev_null:
        raise ValueError("stdin")
    for row in (stdout_row, stderr_row):
        if row[2] != os.O_WRONLY or row[3] != stat.S_IFIFO or row[7]:
            raise ValueError("pipe")
    if stdout_row[4:7] == stderr_row[4:7]:
        raise ValueError("pipe-alias")
    return (argv[1], cwd, incoming_umask, fd_rows, flags)


def _production_signals():
    return (signal.SIGALRM, signal.SIGHUP, signal.SIGINT, signal.SIGQUIT, signal.SIGTERM)


def _production_control_check(control):
    if not isinstance(control, list) or len(control) != 8 or control[4] is not True:
        raise RuntimeError("production-control")
    if control[2] is not None:
        raise InterruptedError("production-termination")
    if control[1] or time.monotonic() >= control[0]:
        raise TimeoutError("overall-deadline")


def _production_control_start(started):
    deadline = started + _OVERALL_SECONDS
    managed = _production_signals()
    old_mask = signal.pthread_sigmask(signal.SIG_BLOCK, managed)
    old_handlers = []
    control = [deadline, False, None, False, True, (), old_mask, False]

    def production_handler(signum, frame):
        if control[4] is not True:
            return
        if signum == signal.SIGALRM:
            if time.monotonic() >= control[0]:
                control[1] = True
            elif control[2] is None:
                control[2] = signum
        elif control[2] is None:
            control[2] = signum
        if control[3] is not True:
            if control[1]:
                raise TimeoutError("overall-deadline")
            raise InterruptedError("production-termination")

    try:
        if time.monotonic() >= deadline:
            raise TimeoutError("overall-deadline")
        if signal.getitimer(signal.ITIMER_REAL) != (0.0, 0.0):
            raise RuntimeError("preexisting-timer")
        if set(signal.sigpending()) & set(managed):
            raise RuntimeError("pending-signal")
        for watched in managed:
            old_handlers.append((watched, signal.signal(watched, production_handler)))
        control[5] = tuple(old_handlers)
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise TimeoutError("overall-deadline")
        signal.setitimer(signal.ITIMER_REAL, remaining, 0.0)
        control[7] = True
        if set(signal.sigpending()) & set(managed):
            raise RuntimeError("pending-signal")
        signal.pthread_sigmask(signal.SIG_UNBLOCK, managed)
        _production_control_check(control)
        return control
    except BaseException:
        control[4] = False
        if control[7]:
            signal.setitimer(signal.ITIMER_REAL, 0.0, 0.0)
            control[7] = False
        for watched, previous in reversed(old_handlers):
            signal.signal(watched, previous)
        signal.pthread_sigmask(signal.SIG_SETMASK, old_mask)
        raise


def _production_control_stop(control, successful):
    if not isinstance(control, list) or len(control) != 8 or control[4] is not True:
        raise RuntimeError("production-control")
    managed = _production_signals()
    stop_error = None
    signal.pthread_sigmask(signal.SIG_BLOCK, managed)
    signal.setitimer(signal.ITIMER_REAL, 0.0, 0.0)
    control[7] = False
    if successful:
        try:
            _production_control_check(control)
            if set(signal.sigpending()) & set(managed):
                raise InterruptedError("production-pending-signal")
        except BaseException as error:
            stop_error = error
    control[4] = False
    for watched, previous in reversed(control[5]):
        signal.signal(watched, previous)
    signal.pthread_sigmask(signal.SIG_SETMASK, control[6])
    if stop_error is not None:
        raise stop_error


def _production_control_scanner_enter(control):
    _production_control_check(control)
    if control[3] is not False:
        raise RuntimeError("scanner-control")
    control[3] = True


def _production_control_scanner_leave(control):
    if control[3] is not True:
        raise RuntimeError("scanner-control")
    control[3] = False
    _production_control_check(control)


def _validate_entry():
    started = time.monotonic()
    argv = tuple(sys.argv)
    control = None
    if argv == (_LAUNCHER, "completion-audit-publish"):
        control = _production_control_start(started)
    try:
        incoming_umask = os.umask(63)
        environment = tuple(sorted(os.environ.items()))
        cwd = os.getcwd()
        fd_rows = _entry_fd_rows()
        dev_null_stat = os.stat(_DEV_NULL, follow_symlinks=False)
        dev_null = (dev_null_stat.st_dev, dev_null_stat.st_ino, dev_null_stat.st_rdev)
        flags = (sys.flags.isolated, sys.flags.dont_write_bytecode, sys.flags.no_site, sys.flags.no_user_site)
        logical_realpath = os.path.realpath(_LOGICAL_EMPTY_CWD)
        cwd_stat = os.stat(".", follow_symlinks=False)
        logical_stat = os.stat(_LOGICAL_EMPTY_CWD, follow_symlinks=True)
        physical_stat = os.stat(_EMPTY_CWD, follow_symlinks=False)
        cwd_binding = (logical_realpath,) + tuple((item.st_dev, item.st_ino, stat.S_IFMT(item.st_mode), item.st_mode & 4095, item.st_uid, item.st_gid, item.st_nlink) for item in (cwd_stat, logical_stat, physical_stat))
        accepted = _validate_entry_model(argv, environment, cwd, incoming_umask, fd_rows, dev_null, flags, cwd_binding)
        return (started, accepted, control)
    except BaseException:
        if control is not None:
            _production_control_stop(control, False)
        raise


def _semantic_project(record):
    if not isinstance(record, bytes) or not record.endswith(b"\n") or b"\x00" in record or b"\r" in record:
        raise ValueError("record")
    occurrences = []
    offset = 0
    while True:
        found = record.find(_SOURCE_HASH_PREFIX, offset)
        if found < 0:
            break
        if found != 0 and record[found - 1:found] != b"\n":
            offset = found + 1
            continue
        value_start = found + len(_SOURCE_HASH_PREFIX)
        value_end = record.find(b"\n", value_start)
        if value_end < 0:
            raise ValueError("source-hash-field")
        value = record[value_start:value_end]
        if len(value) != 64 or any(byte not in b"0123456789abcdef" for byte in value):
            raise ValueError("source-hash-field")
        occurrences.append((value_start, value_end, value.decode("ascii")))
        offset = value_end + 1
    if len(occurrences) != 1:
        raise ValueError("source-hash-field")
    value_start, value_end, value = occurrences[0]
    projected = record[:value_start] + (b"0" * 64) + record[value_end:]
    return (projected, value)


def _semantic_normalize_launcher(source, tree):
    if (
        type(source) is not bytes
        or not isinstance(tree, ast.Module)
        or not source.endswith(b"\n")
        or source.endswith(b"\n\n")
        or source.startswith(b"\xef\xbb\xbf")
        or b"\x00" in source
        or b"\r" in source
    ):
        raise ValueError("semantic-source")
    try:
        decoded = source.decode("utf-8", "strict")
    except UnicodeError as error:
        raise ValueError("semantic-source") from error
    if decoded.encode("utf-8") != source:
        raise ValueError("semantic-source")
    assignments = tuple(
        statement
        for statement in tree.body
        if isinstance(statement, ast.Assign)
        and len(statement.targets) == 1
        and isinstance(statement.targets[0], ast.Name)
        and statement.targets[0].id
        == "IMPLEMENTATION_PREFLIGHT_SEMANTIC_SHA256"
    )
    stores = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and node.id == "IMPLEMENTATION_PREFLIGHT_SEMANTIC_SHA256"
        and isinstance(node.ctx, ast.Store)
    )
    deletes = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and node.id == "IMPLEMENTATION_PREFLIGHT_SEMANTIC_SHA256"
        and isinstance(node.ctx, ast.Del)
    )
    if len(assignments) != 1 or len(stores) != 1 or deletes:
        raise ValueError("semantic-assignment")
    assignment = assignments[0]
    if stores[0] is not assignment.targets[0] or not isinstance(assignment.value, ast.Constant) or type(assignment.value.value) is not str:
        raise ValueError("semantic-assignment")
    value = assignment.value.value
    if not _is_lower_hex(value, 64):
        raise ValueError("semantic-assignment")
    lines = source.splitlines(keepends=True)
    if (
        assignment.lineno != assignment.end_lineno
        or assignment.value.lineno != assignment.value.end_lineno
        or assignment.lineno <= 0
        or assignment.lineno > len(lines)
    ):
        raise ValueError("semantic-coordinate")
    expected_line = (
        b'IMPLEMENTATION_PREFLIGHT_SEMANTIC_SHA256 = "'
        + value.encode("ascii")
        + b'"\n'
    )
    if lines[assignment.lineno - 1] != expected_line or source.count(expected_line) != 1:
        raise ValueError("semantic-raw-line")
    line_start = sum(len(line) for line in lines[:assignment.value.lineno - 1])
    constant_start = line_start + assignment.value.col_offset
    constant_end = line_start + assignment.value.end_col_offset
    if source[constant_start:constant_end] != b'"' + value.encode("ascii") + b'"':
        raise ValueError("semantic-coordinate")
    value_start = constant_start + 1
    value_end = constant_end - 1
    if value_end - value_start != 64:
        raise ValueError("semantic-coordinate")
    normalized = source[:value_start] + b"0" * 64 + source[value_end:]
    if (
        len(normalized) != len(source)
        or normalized.count(b"\n") != source.count(b"\n")
        or normalized[:value_start] != source[:value_start]
        or normalized[value_end:] != source[value_end:]
        or normalized[value_start:value_end] != b"0" * 64
    ):
        raise ValueError("semantic-normalization")
    normalized_again = normalized[:value_start] + b"0" * 64 + normalized[value_end:]
    if normalized_again != normalized:
        raise ValueError("semantic-idempotence")
    normalized_tree = copy.deepcopy(tree)
    normalized_assignment = normalized_tree.body[tree.body.index(assignment)]
    if (
        not isinstance(normalized_assignment, ast.Assign)
        or not isinstance(normalized_assignment.value, ast.Constant)
        or normalized_assignment.value.value != value
    ):
        raise ValueError("semantic-copy")
    normalized_assignment.value.value = "0" * 64
    return (normalized, normalized_tree, (value_start, value_end), value)


def _retained_record_preallocation_layout(record):
    if (
        type(record) is not bytes
        or not record.endswith(b"\n")
        or len(record) <= 0
        or len(record) > _MAX_RECORD_BYTES
        or b"\x00" in record
        or b"\r" in record
        or record.count(_AUTHORITY_BEGIN) != 1
        or record.count(_AUTHORITY_END) != 1
    ):
        raise ValueError("retained-record-layout")
    begin = record.index(_AUTHORITY_BEGIN) + len(_AUTHORITY_BEGIN)
    end = record.index(_AUTHORITY_END)
    if begin >= end:
        raise ValueError("retained-record-layout")
    rows = []
    previous_key = None
    position = begin
    while position < end:
        if len(rows) >= _MAX_AUTHORITY_ITEMS:
            raise ValueError("retained-record-layout-count")
        line_end = record.find(b"\n", position, end)
        if line_end < 0:
            raise ValueError("retained-record-layout")
        separator = record.find(b"=", position, line_end)
        if (
            separator <= position
            or record.find(b"=", separator + 1, line_end) >= 0
            or separator - position > 255
        ):
            raise ValueError("retained-record-layout")
        key_bytes = record[position:separator]
        if any(
            byte
            not in b"abcdefghijklmnopqrstuvwxyz0123456789._-"
            for byte in key_bytes
        ):
            raise ValueError("retained-record-layout")
        try:
            key = key_bytes.decode("ascii", "strict")
        except UnicodeDecodeError as error:
            raise ValueError("retained-record-layout") from error
        if previous_key is not None and key <= previous_key:
            raise ValueError("retained-record-layout")
        value_start = separator + 1
        value_end = line_end
        rows.append((key, position, separator, value_start, value_end, line_end + 1))
        previous_key = key
        position = line_end + 1
    if position != end:
        raise ValueError("retained-record-layout")
    by_key = {row[0]: row for row in rows}
    if len(by_key) != len(rows):
        raise ValueError("retained-record-layout")
    proof_keys = tuple(
        "retained_state_source_proof."
        + str(sequence).zfill(6)
        + ".row_hex"
        for sequence in range(_RETAINED_SOURCE_PROOF_ROWS)
    )
    source_expected_keys = tuple(
        "static_vector."
        + str(192 + sequence).zfill(6)
        + ".expected_hex"
        for sequence in range(_RETAINED_SOURCE_PROOF_ROWS)
    )
    excluded_keys = proof_keys + source_expected_keys + (
        "static_vector_definitions_hex",
        "static_expected_hex",
    )
    if any(key not in by_key for key in excluded_keys) or len(
        set(excluded_keys)
    ) != 54:
        raise ValueError("retained-record-layout-exclusions")

    def lowercase_hex_size(key, maximum, allow_empty):
        row = by_key[key]
        value_start = row[3]
        value_end = row[4]
        encoded_size = value_end - value_start
        if (
            encoded_size % 2 != 0
            or encoded_size // 2 > maximum
            or not allow_empty
            and encoded_size == 0
            or any(
                record[index]
                not in b"0123456789abcdef"
                for index in range(value_start, value_end)
            )
        ):
            raise ValueError("retained-record-layout-hex")
        return encoded_size // 2

    proof_sizes = tuple(
        lowercase_hex_size(
            key, _RETAINED_SOURCE_PROOF_MAX_ROW_BYTES, False
        )
        for key in proof_keys
    )
    expected_sizes = tuple(
        2 * size + len(str(size)) + 3 for size in proof_sizes
    )
    observed_expected_sizes = tuple(
        lowercase_hex_size(key, 1048576, False)
        for key in source_expected_keys
    )
    if (
        any(size <= 0 or size > _RETAINED_SOURCE_PROOF_MAX_ROW_BYTES for size in proof_sizes)
        or any(size > 1048576 for size in expected_sizes)
        or observed_expected_sizes != expected_sizes
        or len(_RETAINED_SOURCE_PROOF_SCHEMA) + sum(proof_sizes)
        > _RETAINED_SOURCE_PROOF_MAX_BYTES
    ):
        raise ValueError("retained-record-layout-proof-size")
    vector_size = lowercase_hex_size(
        "static_vector_definitions_hex", 16777216, False
    )
    output_size = lowercase_hex_size("static_expected_hex", 16777216, False)
    excluded_value_bytes = sum(by_key[key][4] - by_key[key][3] for key in excluded_keys)
    k_value = len(record) - excluded_value_bytes
    predicted = (
        k_value
        + 2 * sum(proof_sizes)
        + 2 * sum(expected_sizes)
        + 2 * vector_size
        + 2 * output_size
    )
    if (
        type(k_value) is not int
        or type(predicted) is not int
        or k_value <= 0
        or k_value > 18446744073709551615
        or predicted <= 0
        or predicted > _MAX_RECORD_BYTES
        or predicted != len(record)
        or 2 * vector_size > 33554432
    ):
        raise ValueError("retained-record-layout-size")
    source_hash_row = by_key.get("launcher_source_sha256")
    if (
        source_hash_row is None
        or source_hash_row[4] - source_hash_row[3] != 64
        or any(
            record[index] not in b"0123456789abcdef"
            for index in range(source_hash_row[3], source_hash_row[4])
        )
    ):
        raise ValueError("retained-record-layout-source-hash")
    return (
        tuple(rows),
        (source_hash_row[3], source_hash_row[4]),
        proof_sizes,
        expected_sizes,
        vector_size,
        output_size,
        k_value,
        predicted,
    )


def _retained_rebuild_record_projection(
    record,
    layout,
    retained_rows,
    vector_definitions,
    static_expected,
):
    if (
        type(record) is not bytes
        or type(layout) is not tuple
        or len(layout) != 8
        or type(layout[0]) is not tuple
        or type(retained_rows) is not tuple
        or len(retained_rows) != _RETAINED_SOURCE_PROOF_ROWS
        or any(type(row) is not bytes for row in retained_rows)
        or type(vector_definitions) is not bytes
        or type(static_expected) is not bytes
    ):
        raise ValueError("retained-record-rebuild-input")
    (
        rows,
        source_hash_span,
        observed_proof_sizes,
        observed_expected_sizes,
        observed_vector_size,
        observed_output_size,
        k_value,
        observed_total,
    ) = layout
    proof_sizes = tuple(len(row) for row in retained_rows)
    if (
        proof_sizes != observed_proof_sizes
        or any(
            size <= 0 or size > _RETAINED_SOURCE_PROOF_MAX_ROW_BYTES
            for size in proof_sizes
        )
    ):
        raise ValueError("retained-record-rebuild-proof-size")
    expected_sizes = tuple(
        2 * proof_size + len(str(proof_size)) + 3
        for proof_size in proof_sizes
    )
    if (
        expected_sizes != observed_expected_sizes
        or any(
            size > 1048576 for size in expected_sizes
        )
        or len(_RETAINED_SOURCE_PROOF_SCHEMA) + sum(proof_sizes)
        > _RETAINED_SOURCE_PROOF_MAX_BYTES
        or len(vector_definitions) != observed_vector_size
        or len(static_expected) != observed_output_size
        or len(vector_definitions) > 16777216
        or 2 * len(vector_definitions) > 33554432
        or len(static_expected) > 16777216
    ):
        raise ValueError("retained-record-rebuild-component-size")
    proof_keys = tuple(
        "retained_state_source_proof."
        + str(sequence).zfill(6)
        + ".row_hex"
        for sequence in range(_RETAINED_SOURCE_PROOF_ROWS)
    )
    source_expected_keys = tuple(
        "static_vector."
        + str(192 + sequence).zfill(6)
        + ".expected_hex"
        for sequence in range(_RETAINED_SOURCE_PROOF_ROWS)
    )
    expected_rows = tuple(_canonical_value(row) for row in retained_rows)
    if tuple(len(row) for row in expected_rows) != expected_sizes:
        raise ValueError("retained-record-rebuild-component-size")
    replacement_values = {
        key: retained_rows[sequence].hex().encode("ascii")
        for sequence, key in enumerate(proof_keys)
    }
    replacement_values.update(
        {
            key: expected_rows[sequence].hex().encode("ascii")
            for sequence, key in enumerate(source_expected_keys)
        }
    )
    replacement_values["static_vector_definitions_hex"] = (
        vector_definitions.hex().encode("ascii")
    )
    replacement_values["static_expected_hex"] = (
        static_expected.hex().encode("ascii")
    )
    excluded_keys = proof_keys + source_expected_keys + (
        "static_vector_definitions_hex",
        "static_expected_hex",
    )
    if (
        tuple(sorted(replacement_values)) != tuple(sorted(excluded_keys))
        or len(replacement_values) != 54
    ):
        raise ValueError("retained-record-rebuild-exclusions")
    by_key = {row[0]: row for row in rows}
    if len(by_key) != len(rows) or any(key not in by_key for key in excluded_keys):
        raise ValueError("retained-record-rebuild-layout")
    predicted = (
        k_value
        + 2 * sum(proof_sizes)
        + 2 * sum(expected_sizes)
        + 2 * len(vector_definitions)
        + 2 * len(static_expected)
    )
    if (
        type(k_value) is not int
        or type(predicted) is not int
        or k_value <= 0
        or k_value > 18446744073709551615
        or predicted <= 0
        or predicted > _MAX_RECORD_BYTES
        or predicted != observed_total
        or predicted != len(record)
    ):
        raise ValueError("retained-record-rebuild-size")
    for key, replacement in replacement_values.items():
        row = by_key[key]
        if (
            row[4] - row[3] != len(replacement)
            or any(byte not in b"0123456789abcdef" for byte in replacement)
        ):
            raise ValueError("retained-record-rebuild-field")
    if (
        type(source_hash_span) is not tuple
        or len(source_hash_span) != 2
        or source_hash_span[1] - source_hash_span[0] != 64
    ):
        raise ValueError("retained-record-rebuild-source-hash")
    ordered_replacements = tuple(
        sorted(
            tuple(
                (by_key[key][3], by_key[key][4], value)
                for key, value in replacement_values.items()
            )
            + (
                (
                    source_hash_span[0],
                    source_hash_span[1],
                    b"0" * 64,
                ),
            )
        )
    )
    if any(
        left[1] > right[0]
        for left, right in zip(
            ordered_replacements, ordered_replacements[1:]
        )
    ):
        raise ValueError("retained-record-rebuild-overlap")
    fragments = []
    position = 0
    for value_start, value_end, replacement in ordered_replacements:
        fragments.append(record[position:value_start])
        fragments.append(replacement)
        position = value_end
    fragments.append(record[position:])
    rebuilt = b"".join(fragments)
    if len(rebuilt) != predicted:
        raise ValueError("retained-record-rebuild-total")
    return rebuilt


def _parse_authority_payload(payload):
    if not payload or not payload.endswith(b"\n") or b"\x00" in payload or b"\r" in payload:
        raise ValueError("authority")
    lines = payload[:-1].split(b"\n")
    keys = []
    values = {}
    for line in lines:
        if line.count(b"=") != 1:
            raise ValueError("authority-row")
        key_bytes, value_bytes = line.split(b"=", 1)
        try:
            key = key_bytes.decode("ascii")
            value = value_bytes.decode("ascii")
        except UnicodeDecodeError as error:
            raise ValueError("authority-ascii") from error
        empty_expected_hex = (
            len(key_bytes) == len(b"static_vector.") + 6 + len(b".expected_hex")
            and key_bytes.startswith(b"static_vector.")
            and key_bytes.endswith(b".expected_hex")
            and all(
                byte in b"0123456789"
                for byte in key_bytes[
                    len(b"static_vector."):len(b"static_vector.") + 6
                ]
            )
        )
        if not key or len(key) > 255 or (not value and not empty_expected_hex) or len(value) > _MAX_RECORD_BYTES:
            raise ValueError("authority-field")
        if any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-" for character in key):
            raise ValueError("authority-key")
        if key in values:
            raise ValueError("authority-duplicate")
        keys.append(key)
        values[key] = value
    if keys != sorted(keys):
        raise ValueError("authority-order")
    return values


def _parse_record_authority(record):
    if record.count(_AUTHORITY_BEGIN) != 1 or record.count(_AUTHORITY_END) != 1:
        raise ValueError("authority-block")
    begin = record.index(_AUTHORITY_BEGIN) + len(_AUTHORITY_BEGIN)
    end = record.index(_AUTHORITY_END)
    if end <= begin:
        raise ValueError("authority-block")
    return _parse_authority_payload(record[begin:end])


def _indexed_key(prefix, index, suffix):
    return prefix + "." + str(index).zfill(6) + "." + suffix


def _authority_take_count(values, key):
    if key not in values:
        raise ValueError("authority-missing")
    count = _decimal(values[key], False)
    if count > _MAX_AUTHORITY_ITEMS:
        raise ValueError("authority-count")
    return count


def _authority_take_indexed(values, prefix, count, suffixes):
    rows = []
    for index in range(count):
        row = []
        for suffix in suffixes:
            key = _indexed_key(prefix, index, suffix)
            if key not in values:
                raise ValueError("authority-missing")
            row.append(values[key])
        rows.append(tuple(row))
    return tuple(rows)


def _parse_retained_source_proof_authority(values, rows):
    if (
        type(rows) is not tuple
        or len(rows) != _RETAINED_SOURCE_PROOF_ROWS
        or tuple(row[0] for row in _RETAINED_SOURCE_ROLES)
        != _RETAINED_SOURCE_CASES
        or tuple(row[0] for row in _RETAINED_SOURCE_SUBMUTATIONS)
        != _RETAINED_SOURCE_CASES
        or tuple(row[0] for row in _RETAINED_SOURCE_MUTATION_FAILURES)
        != _RETAINED_SOURCE_CASES
        or tuple(
            tuple(item[0] for item in row[1])
            for row in _RETAINED_SOURCE_MUTATION_FAILURES
        )
        != tuple(row[1] for row in _RETAINED_SOURCE_SUBMUTATIONS)
        or tuple(row[0] for row in _RETAINED_SOURCE_PROOF_INVENTORY)
        != _RETAINED_SOURCE_CASES
    ):
        raise ValueError("retained-source-proof-inventory")
    keys = (
        "kind",
        "sequence",
        "case",
        "source_role",
        "controller_source_sha256",
        "launcher_semantic_source_kind",
        "launcher_semantic_source_sha256",
        "launcher_raw_source_reference",
        "lexical_owner",
        "node_kind",
        "spans",
        "occurrence_count",
        "normalized_def_use",
        "polarity",
        "dominators",
        "success_exits",
        "failure_exits",
        "expected",
        "result_token",
    )
    span_keys = (
        "source_role",
        "start_line",
        "start_utf8_byte_column",
        "end_line",
        "end_utf8_byte_column",
    )

    def accepted_span(value):
        if type(value) is not dict or tuple(value) != span_keys:
            raise ValueError("retained-source-proof-span")
        if value["source_role"] not in ("controller-source", "launcher-source"):
            raise ValueError("retained-source-proof-span")
        numbers = tuple(value[key] for key in span_keys[1:])
        if any(type(number) is not int or number < 0 for number in numbers):
            raise ValueError("retained-source-proof-span")
        if numbers[0] == 0 or (numbers[2], numbers[3]) <= (numbers[0], numbers[1]):
            raise ValueError("retained-source-proof-span")
        return tuple(value[key] for key in span_keys)

    accepted_rows = []
    semantic_source_sha256 = None
    total_bytes = len(_RETAINED_SOURCE_PROOF_SCHEMA)
    for sequence, row in enumerate(rows):
        if type(row) is not tuple or len(row) != 1 or type(row[0]) is not str:
            raise ValueError("retained-source-proof-row")
        row_hex = row[0]
        if (
            not row_hex
            or len(row_hex) % 2 != 0
            or len(row_hex) // 2 > _RETAINED_SOURCE_PROOF_MAX_ROW_BYTES
        ):
            raise ValueError("retained-source-proof-size")
        row_bytes = _decode_hex(row_hex, _RETAINED_SOURCE_PROOF_MAX_ROW_BYTES)
        row_size = len(row_bytes)
        encoded_size = 2 * row_size + len(str(row_size)) + 3
        if row_size == 0 or encoded_size > 1048576:
            raise ValueError("retained-source-proof-size")
        total_bytes += row_size
        if total_bytes > _RETAINED_SOURCE_PROOF_MAX_BYTES:
            raise ValueError("retained-source-proof-size")
        if row_bytes.count(b"\n") != 1 or not row_bytes.endswith(b"\n"):
            raise ValueError("retained-source-proof-framing")
        value = _decode_canonical_json_line(row_bytes)
        if type(value) is not dict or tuple(value) != keys:
            raise ValueError("retained-source-proof-schema")
        case_name, result_token, expected = _RETAINED_SOURCE_PROOF_INVENTORY[sequence]
        source_role = _RETAINED_SOURCE_ROLES[sequence][1]
        if (
            value["kind"] != "retained-state-source-proof"
            or type(value["sequence"]) is not int
            or value["sequence"] != sequence
            or value["case"] != case_name
            or value["source_role"] != source_role
            or value["controller_source_sha256"] != values["controller_sha256"]
            or not _is_lower_hex(value["controller_source_sha256"], 64)
            or value["launcher_semantic_source_kind"] != _RETAINED_SOURCE_KIND
            or not _is_lower_hex(value["launcher_semantic_source_sha256"], 64)
            or value["launcher_semantic_source_sha256"] == "0" * 64
            or value["launcher_raw_source_reference"] != _RETAINED_SOURCE_REFERENCE
            or _token(value["lexical_owner"]) != value["lexical_owner"]
            or _token(value["node_kind"]) != value["node_kind"]
            or value["polarity"] != ("positive" if sequence == 0 else "negative")
            or value["expected"] != expected
            or value["result_token"] != result_token
        ):
            raise ValueError("retained-source-proof-value")
        if semantic_source_sha256 is None:
            semantic_source_sha256 = value["launcher_semantic_source_sha256"]
        elif value["launcher_semantic_source_sha256"] != semantic_source_sha256:
            raise ValueError("retained-source-proof-identity")
        if type(value["spans"]) is not list or not value["spans"]:
            raise ValueError("retained-source-proof-spans")
        accepted_spans = tuple(accepted_span(span) for span in value["spans"])
        if (
            type(value["occurrence_count"]) is not int
            or value["occurrence_count"] <= 0
            or value["occurrence_count"] != len(accepted_spans)
            or type(value["normalized_def_use"]) is not list
        ):
            raise ValueError("retained-source-proof-occurrences")
        for field in ("dominators", "success_exits", "failure_exits"):
            if type(value[field]) is not list:
                raise ValueError("retained-source-proof-flow")
            accepted = tuple(accepted_span(span) for span in value[field])
            if any(span not in accepted_spans for span in accepted):
                raise ValueError("retained-source-proof-flow")
        accepted_rows.append(row_bytes)
    proof_count = _decimal(values["retained_state_source_proof_count"], True)
    proof_lf_count = _decimal(values["retained_state_source_proof_lf_count"], True)
    proof_bytes = _decimal(values["retained_state_source_proof_bytes"], True)
    proof_sha256 = values["retained_state_source_proof_sha256"]
    if (
        proof_count != _RETAINED_SOURCE_PROOF_ROWS
        or proof_lf_count != _RETAINED_SOURCE_PROOF_LF_COUNT
        or not _is_lower_hex(proof_sha256, 64)
        or total_bytes != proof_bytes
    ):
        raise ValueError("retained-source-proof-binding")
    proof_record = _RETAINED_SOURCE_PROOF_SCHEMA + b"".join(accepted_rows)
    if (
        len(proof_record) != proof_bytes
        or proof_record.count(b"\n") != proof_lf_count
        or _sha256(proof_record) != proof_sha256
    ):
        raise ValueError("retained-source-proof-binding")
    return (
        tuple(accepted_rows),
        (proof_count, proof_lf_count, proof_bytes, proof_sha256),
    )


def _parse_authority(record):
    values = _parse_record_authority(record)
    scalar_keys = ("acquisition_root_path_hex", "audit_parent_path_hex", "audit_parent_snapshot_hex", "completion_digest_basename_hex", "completion_review_basename_hex", "completion_tsv_basename_hex", "controller_function_count", "controller_literal_count", "controller_path_hex", "controller_sha256", "env_path_hex", "env_sha256", "launcher_source_bytes", "launcher_source_lines", "launcher_source_sha256", "libsystem_path_hex", "libsystem_sha256", "pre_runtime_check_count", "pre_runtime_gate_count", "pre_runtime_phase_path_hex", "pre_runtime_result_path_hex", "pre_runtime_semantic_gate_count", "provisioner_function_count", "provisioner_literal_count", "provisioner_path_hex", "provisioner_sha256", "python_path_hex", "python_sha256", "repository_path_hex", "retained_state_combined_case_count", "retained_state_direct_case_count", "retained_state_direct_case_names_sha256", "retained_state_source_case_count", "retained_state_source_case_names_sha256", "retained_state_source_proof_bytes", "retained_state_source_proof_count", "retained_state_source_proof_lf_count", "retained_state_source_proof_sha256", "retained_state_table_bytes", "retained_state_table_hex", "retained_state_table_rows", "retained_state_table_sha256", "scanner_arg_count", "schema", "stable_count", "static_expected_bytes", "static_expected_hex", "static_expected_lines", "static_expected_sha256", "static_vector_count", "static_vector_definitions_hex", "static_vector_definitions_sha256")
    for key in scalar_keys:
        if key not in values:
            raise ValueError("authority-missing")
    scanner_count = _authority_take_count(values, "scanner_arg_count")
    stable_count = _authority_take_count(values, "stable_count")
    completion_count = _authority_take_count(values, "completion_object_count")
    controller_function_count = _authority_take_count(values, "controller_function_count")
    controller_literal_count = _authority_take_count(values, "controller_literal_count")
